var import_obsidian4 = require("obsidian");
var Indexer = class {
  constructor(app, geminiService, vectorStore) {
    this.app = app;
    this.geminiService = geminiService;
    this.vectorStore = vectorStore;
  }
  async indexVault() {
    new import_obsidian4.Notice("Starting Vault Indexing...");
    const files = this.app.vault.getMarkdownFiles();
    let totalFiles = files.length;
    let processed = 0;
    const batchSize = 5;
    for (let i2 = 0; i2 < totalFiles; i2 += batchSize) {
      const batch = files.slice(i2, i2 + batchSize);
      await Promise.all(batch.map((file) => this.indexFile(file)));
      processed += batch.length;
      if (processed % 10 === 0) {
        new import_obsidian4.Notice(`Indexed ${processed}/${totalFiles} files...`);
      }
    }
    new import_obsidian4.Notice("Vault Indexing Complete!");
  }
  async indexFile(file) {
    try {
      const content = await this.app.vault.read(file);
      const enrichedContent = await this.processImages(content, file.path);
      const chunks = this.chunkText(enrichedContent, 1e3);
      const documents = chunks.map((chunk, index) => ({
        id: `${file.path}#${index}`,
        content: chunk,
        metadata: {
          filePath: file.path,
          fileName: file.basename,
          chunkIndex: index,
          docType: "markdown"
        }
      }));
      const embeddedDocs = await this.geminiService.batchEmbedDocuments(documents);
      await this.vectorStore.addDocuments(embeddedDocs);
    } catch (e2) {
      console.error(`Failed to index file ${file.path}:`, e2);
    }
  }
  async processImages(text, sourcePath) {
    const imageRegex = /!\[\[(.*?)(?:\|.*?)?\]\]/g;
    let match;
    let processedText = text;
    const replacements = [];
    while ((match = imageRegex.exec(text)) !== null) {
      const originalLink = match[0];
      const imageName = match[1];
      const imageFile = this.app.metadataCache.getFirstLinkpathDest(imageName, sourcePath);
      if (imageFile && ["png", "jpg", "jpeg", "webp"].includes(imageFile.extension)) {
        try {
          const arrayBuffer = await this.app.vault.readBinary(imageFile);
          const mimeType = this.getMimeType(imageFile.extension);
          const caption = await this.geminiService.generateImageCaption(arrayBuffer, mimeType);
          if (caption) {
            replacements.push({
              match: originalLink,
              replacement: `${originalLink}

[Image Content: ${caption}]
`
            });
          }
        } catch (e2) {
          console.error(`Failed to process image ${imageName}:`, e2);
        }
      }
    }
    for (const rep of replacements) {
      processedText = processedText.replace(rep.match, rep.replacement);
    }
    return processedText;
  }
  chunkText(text, maxLength) {
    const paragraphs = text.split(/\n\n+/);
    const chunks = [];
    let currentChunk = "";
    for (const para of paragraphs) {
      if (currentChunk.length + para.length > maxLength) {
        if (currentChunk)
          chunks.push(currentChunk);
        currentChunk = para;
      } else {
        currentChunk += (currentChunk ? "\n\n" : "") + para;
      }
    }
    if (currentChunk)
      chunks.push(currentChunk);
    return chunks;
  }
  getMimeType(extension) {
    switch (extension.toLowerCase()) {
      case "png":
        return "image/png";
      case "jpg":
      case "jpeg":
        return "image/jpeg";
      case "webp":
        return "image/webp";
      default:
        return "application/octet-stream";
    }
  }
};

// src/rag/SimpleVectorStore.ts
var INDEX_FILE = ".gemini_index.json";
var SimpleVectorStore = class {
  constructor(app) {
    this.name = "SimpleVectorStore";
    this.documents = [];
    this.app = app;
  }
  async initialize() {
    try {
      const exists = await this.app.vault.adapter.exists(INDEX_FILE);
      if (exists) {
        const data = await this.app.vault.adapter.read(INDEX_FILE);
        const json = JSON.parse(data);
        if (Array.isArray(json)) {
          this.documents = json;
          console.log(`Loaded ${this.documents.length} documents from index.`);
        }
      }
    } catch (e2) {
      console.error("Failed to load index:", e2);
    }
  }
  async addDocuments(documents) {
    this.documents.push(...documents);
    await this.save();
  }
  async deleteDocumentsByPath(filePath) {
    this.documents = this.documents.filter((d) => d.metadata.filePath !== filePath);
    await this.save();
  }
  async similaritySearch(queryEmbedding, limit) {
    if (this.documents.length === 0)
      return [];
    const scoredDocs = this.documents.map((doc) => {
      if (!doc.embedding)
        return { doc, score: -1 };
      const score = this.cosineSimilarity(queryEmbedding, doc.embedding);
      return { doc, score };
    });
    scoredDocs.sort((a, b) => b.score - a.score);
    return scoredDocs.slice(0, limit).map((d) => d.doc);
  }
  async save() {
    try {
      const data = JSON.stringify(this.documents);
      await this.app.vault.adapter.write(INDEX_FILE, data);
    } catch (e2) {
      console.error("Failed to save index:", e2);
    }
  }
  cosineSimilarity(a, b) {
    if (a.length !== b.length)
      return 0;
    let dotProduct = 0;
    let magnitudeA = 0;
    let magnitudeB = 0;
    for (let i2 = 0; i2 < a.length; i2++) {
      dotProduct += a[i2] * b[i2];
      magnitudeA += a[i2] * a[i2];
      magnitudeB += b[i2] * b[i2];
    }
    magnitudeA = Math.sqrt(magnitudeA);
    magnitudeB = Math.sqrt(magnitudeB);
    if (magnitudeA === 0 || magnitudeB === 0)
      return 0;
    return dotProduct / (magnitudeA * magnitudeB);
  }
};

